#!/usr/bin/env python3
"""
Round 214o (culprits-tiles-more), 15 October 2026. Needs round213o_tiles.py.

- gem_solar.py: the run failed ("could not get the archive under GitHub's 100
  MB limit": about 104,000 phases, 32 columns, at every zoom). Now two tiers,
  as inpe_fire does: zooms 0-7 carry every phase with its name, phase,
  capacity, status, country and GEM ids; zooms 8-10 every phase with every
  column; joined with tile-join. Tried here on the February 2026 download:
  73.7 MB, 103,940 phases, none left out.
- reach.py:
  - stars.json keeps each star's constellation and whether its name is a
    proper name (for the sky chart's labels);
  - masses.json: every Wikidata item with a mass, a distance from Earth, a
    right ascension and a declination (CC0), for gravity's fabric and gravity
    reaching Earth;
  - life.json: every row of Wikipedia's List of potentially habitable
    exoplanets and List of ocean worlds, placed by Wikidata or Horizons.

Afterwards run refresh with gem_solar, reach (reach takes a while).
Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/reach.py': '', 'scripts/gem_solar.py': ''}


def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round214o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round214o_tiles: wrote {path}")
    if not changed:
        print("round214o_tiles: already applied")


if __name__ == "__main__":
    main()
